    dy = 0

    # Helper: safe check within bounds if grid provided
    def in_bounds(x, y):
        if grid is None:
            return True
        h = grid.get("height")
        w = grid.get("width")
        if h is None or w is None:
            return True
        return 0 <= x < w and 0 <= y < h

