        w = grid.get("width")
        h = grid.get("height")
        if w and h:
            cx, cy = w // 2, h // 2
            dx_c = 0
            dy_c = 0
            if x < cx:
                dx_c = 1
            elif x > cx:
                dx_c = -1
            if y < cy:
                dy_c = 1
            elif y > cy:
                dy_c = -1
            if dx_c != 0 or dy_c != 0:
